const IMAGES = {"es_duo.webp": "", "es_s01.webp": "", "es_s02.webp": "", "es_s03.webp": "", "es_s04.webp": "", "es_s05.webp": "", "icon.png": "", "icon.webp": "", "ja_duo.webp": "", "ja_s01.webp": "", "ja_s02.webp": "", "ja_s03.webp": "", "ja_s04.webp": "", "ja_s05.webp": "", "og.png": "", "zh-Hans_duo.webp": "", "zh-Hans_s01.webp": "", "zh-Hans_s02.webp": "", "zh-Hans_s03.webp": "", "zh-Hans_s04.webp": "", "zh-Hans_s05.webp": "", "zh-Hant_duo.webp": "", "zh-Hant_s01.webp": "", "zh-Hant_s02.webp": "", "zh-Hant_s03.webp": "", "zh-Hant_s04.webp": "", "zh-Hant_s05.webp": ""};
const AUDIO = {"baggage_claim.mp3": "", "check_bill.mp3": "", "check_in.mp3": "", "credit_card.mp3": ""};
const SITEMAP = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>https://englishgo.appengine.fun/</loc><priority>1.0</priority></url>\n  <url><loc>https://englishgo.appengine.fun/?lang=zh-Hant</loc><priority>0.9</priority></url>\n  <url><loc>https://englishgo.appengine.fun/?lang=zh-Hans</loc><priority>0.9</priority></url>\n  <url><loc>https://englishgo.appengine.fun/?lang=es</loc><priority>0.9</priority></url>\n  <url><loc>https://englishgo.appengine.fun/?lang=ja</loc><priority>0.9</priority></url>\n  <url><loc>https://englishgo.appengine.fun/privacy</loc><priority>0.7</priority></url>\n  <url><loc>https://englishgo.appengine.fun/support</loc><priority>0.7</priority></url>\n</urlset>";
const ROBOTS = "User-agent: *\nAllow: /\nSitemap: https://englishgo.appengine.fun/sitemap.xml\n";

function b64ToBytes(b64) {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

function resolveLang(request) {
  const url = new URL(request.url);
  const q = url.searchParams.get("lang");
  if (q && PAGES[q]) return q;
  if (q === "zh-TW" || q === "tw" || q === "hk") return "zh-Hant";
  if (q === "zh-CN" || q === "cn" || q === "zh") return "zh-Hans";
  if (q === "jp" || q === "ja-JP") return "ja";
  const accept = (request.headers.get("accept-language") || "").toLowerCase();
  if (accept.includes("zh-tw") || accept.includes("zh-hk") || accept.includes("zh-hant")) return "zh-Hant";
  if (accept.includes("zh")) return "zh-Hans";
  if (accept.includes("es")) return "es";
  if (accept.includes("ja")) return "ja";
  return "en";
}

export default {
  async fetch(request) {
    const pathname = new URL(request.url).pathname;
    if (pathname === "/sitemap.xml") {
      return new Response(SITEMAP, { headers: { "content-type": "application/xml;charset=UTF-8", "cache-control": "public, max-age=86400" } });
    }
    if (pathname === "/robots.txt") {
      return new Response(ROBOTS, { headers: { "content-type": "text/plain;charset=UTF-8", "cache-control": "public, max-age=86400" } });
    }
    if (pathname.startsWith("/images/")) {
      const name = pathname.slice("/images/".length);
      if (IMAGES[name]) {
        const ct = name.endsWith(".png") ? "image/png" : "image/webp";
        return new Response(b64ToBytes(IMAGES[name]), { headers: { "content-type": ct, "cache-control": "public, max-age=31536000, immutable" } });
      }
      return new Response("Not Found", { status: 404 });
    }
    if (pathname.startsWith("/audio/")) {
      const name = pathname.slice("/audio/".length);
      if (AUDIO[name]) {
        return new Response(b64ToBytes(AUDIO[name]), { headers: { "content-type": "audio/mpeg", "accept-ranges": "bytes", "cache-control": "public, max-age=31536000, immutable" } });
      }
      return new Response("Not Found", { status: 404 });
    }
    const lang = resolveLang(request);
    const htmlHeaders = {
      "content-type": "text/html;charset=UTF-8",
      "cache-control": "public, max-age=0, must-revalidate",
      "vary": "Accept-Language"
    };
    if (pathname === "/privacy" || pathname === "/privacy.html") {
      return new Response(PRIVACY_PAGES[lang] || PRIVACY_PAGES.en, { headers: htmlHeaders });
    }
    if (pathname === "/support" || pathname === "/support.html") {
      return new Response(SUPPORT_PAGES[lang] || SUPPORT_PAGES.en, { headers: htmlHeaders });
    }
    return new Response(PAGES[lang] || PAGES.en, { headers: htmlHeaders });
  }
};
